package ru.neverland.townycouncil;

import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.concurrent.CompletionStage;
import java.util.function.Supplier;
import org.bukkit.Material;
import org.bukkit.entity.Player;
import org.bukkit.command.CommandSender;
import org.bukkit.event.*;
import org.bukkit.event.inventory.*;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.inventory.*;
import com.palmergames.bukkit.towny.TownyAPI;
import com.palmergames.bukkit.towny.object.Town;
import ru.neverland.core.*;
import static ru.neverland.townycouncil.Delegations.*;

public final class DelegationMenus implements Listener {
    private record View(UUID viewer,Inventory back,Map<Integer,Runnable> actions) implements InventoryHolder{public Inventory getInventory(){return null;}}
    private record Quote(UUID id,long expires,Supplier<CompletionStage<State>> action){}
    private final NeverLandTownyCouncil plugin;private final CouncilService council;private final DelegationService service;private final Map<UUID,Quote> quotes=new HashMap<>();
    private static final DateTimeFormatter DATE=DateTimeFormatter.ofPattern("dd.MM.yyyy HH:mm").withZone(ZoneId.of("Europe/Moscow"));
    public DelegationMenus(NeverLandTownyCouncil plugin,CouncilService council,DelegationService service){this.plugin=plugin;this.council=council;this.service=service;}
    static String date(long value){return DATE.format(Instant.ofEpochMilli(value))+" МСК";}
    private static void tell(Player p,String text){CouncilCommand.tell(p,text);}
    public boolean handles(String action){return Set.of("delegations","delegate","undelegate","delegate-confirm","delegate-cancel").contains(action);}
    private Town own(Player p){if(!p.hasPermission("neverlandtownycouncil.use"))throw new IllegalArgumentException("Нет права просмотра совета");var t=council.ownTown(p.getUniqueId());if(t==null)throw new IllegalArgumentException("Сначала вступите в город");return t;}
    public void command(CommandSender sender,String[] args){if(!(sender instanceof Player p))throw new IllegalArgumentException("Временные права настраивает мэр в игре");var town=own(p);switch(args[0].toLowerCase(Locale.ROOT)){
        case "delegations"->open(p,town,0);
        case "delegate"->{if(args.length<5)throw new IllegalArgumentException("/council delegate <житель> <действие> <часы 1–720> <причина>");var r=TownyAPI.getInstance().getResident(args[1]);if(r==null)throw new IllegalArgumentException("Житель не найден");propose(p,town,r.getUUID(),TownAction.parse(args[2]),Integer.parseInt(args[3]),String.join(" ",Arrays.copyOfRange(args,4,args.length)));}
        case "undelegate"->{if(args.length!=3)throw new IllegalArgumentException("/council undelegate <житель> <действие>");var r=TownyAPI.getInstance().getResident(args[1]);if(r==null)throw new IllegalArgumentException("Житель не найден");var g=service.state().grants().get(town.getUUID()+"/"+r.getUUID()+"/"+TownAction.parse(args[2]).id());if(g==null)throw new IllegalArgumentException("Поручение не найдено");revoke(p,town,g);}
        case "delegate-confirm"->{if(args.length!=2)throw new IllegalArgumentException("Используйте кнопку подтверждения");confirm(p,UUID.fromString(args[1]));}
        case "delegate-cancel"->{quotes.remove(p.getUniqueId());tell(p,"Предварительное действие отменено.");}
        default->throw new IllegalArgumentException("Неизвестное действие");}}
    private Inventory menu(Player p,String title,Map<Integer,Runnable> actions){var previous=p.getOpenInventory().getTopInventory();var back=previous.getHolder() instanceof View v?v.back():MenuStyle.previousMenu(p);var menu=MenuStyle.inventory(plugin,new View(p.getUniqueId(),back,actions),54,title);button(menu,actions,45,Material.ARROW,back==null?"Закрыть":"Назад",List.of(),()->MenuStyle.returnTo(p,back));return menu;}
    private static void button(Inventory menu,Map<Integer,Runnable> actions,int slot,Material icon,String title,List<String> lore,Runnable action){var item=new ItemStack(icon);var meta=item.getItemMeta();meta.setDisplayName(MenuStyle.nameLegacy("&f"+title));meta.setLore(MenuStyle.loreStrings(lore));item.setItemMeta(meta);menu.setItem(slot,item);if(action!=null)actions.put(slot,action);}
    public void open(Player p,Town town,int requested){own(p);if(!town.equals(council.ownTown(p.getUniqueId())))throw new IllegalArgumentException("Временные поручения видны жителям своего города");boolean mayor=council.mayEditAccess(p,town);var rows=service.state().grants().values().stream().filter(g->g.town().equals(town.getUUID())&&(mayor||g.resident().equals(p.getUniqueId()))).sorted(Comparator.comparingLong(Grant::grantedAt).reversed()).toList();int pages=Math.max(1,(rows.size()+35)/36),page=Math.min(Math.max(0,requested),pages-1);var actions=new HashMap<Integer,Runnable>();var menu=menu(p,"Временные права • "+(page+1)+"/"+pages,actions);
        for(int i=page*36;i<Math.min(rows.size(),(page+1)*36);i++){var g=rows.get(i);boolean active=service.active(g.town(),g.resident(),TownAction.parse(g.action()));var lines=new ArrayList<>(List.of("&7Житель: &f"+CouncilMenus.name(g.resident()),"&7Действует до: &f"+date(g.expiresAt()),"&7Кто выдал: &f"+g.actor(),"&7Причина: &f"+g.reason(),g.revoked()?"&7Отозвано мэром":active?"&aПоручение действует":"&7Срок истёк или условия больше не выполнены","&7Независимые права жителя сохраняются."));if(mayor&&!g.revoked())lines.add("&fНажмите, чтобы отозвать.");button(menu,actions,i-page*36,active?Material.CLOCK:Material.GRAY_DYE,TownAction.parse(g.action()).title(),lines,mayor&&!g.revoked()?()->revoke(p,town,g):null);}
        if(rows.isEmpty())button(menu,actions,13,Material.PAPER,"Временных поручений пока нет",List.of("&7Обычные должности и личные правила сохранены."),null);
        if(mayor)button(menu,actions,49,Material.WRITABLE_BOOK,"Выдать временные права",List.of("&7Выберите жителя, действие и срок.","&7Перед выдачей будет подтверждение."),()->residents(p,town,0));
        if(page>0)button(menu,actions,46,Material.ARROW,"Предыдущая страница",List.of(),()->open(p,town,page-1));if(page+1<pages)button(menu,actions,53,Material.ARROW,"Следующая страница",List.of(),()->open(p,town,page+1));p.openInventory(menu);
    }
    private void residents(Player p,Town town,int requested){if(!council.mayEditAccess(p,town))throw new IllegalArgumentException("Доступно только мэру");var rows=town.getResidents().stream().filter(r->!r.getUUID().equals(p.getUniqueId())).sorted(Comparator.comparing(r->r.getName().toLowerCase(Locale.ROOT))).toList();int pages=Math.max(1,(rows.size()+35)/36),page=Math.min(Math.max(0,requested),pages-1);var actions=new HashMap<Integer,Runnable>();var menu=menu(p,"Выбрать жителя",actions);for(int i=page*36;i<Math.min(rows.size(),(page+1)*36);i++){var r=rows.get(i);button(menu,actions,i-page*36,Material.PLAYER_HEAD,r.getName(),List.of("&7Выбрать действие, затем срок."),()->actions(p,town,r.getUUID()));}if(page>0)button(menu,actions,46,Material.ARROW,"Предыдущая страница",List.of(),()->residents(p,town,page-1));if(page+1<pages)button(menu,actions,53,Material.ARROW,"Следующая страница",List.of(),()->residents(p,town,page+1));p.openInventory(menu);}
    private void actions(Player p,Town town,UUID resident){var actions=new HashMap<Integer,Runnable>();var menu=menu(p,"Поручить действие",actions);int slot=0;for(var kind:TownAction.values())button(menu,actions,slot++,Material.PAPER,kind.title(),List.of("&7"+kind.description(),"&7Житель: &f"+CouncilMenus.name(resident),"&7Выбрать срок поручения."),()->duration(p,town,resident,kind));p.openInventory(menu);}
    private void duration(Player p,Town town,UUID resident,TownAction action){var actions=new HashMap<Integer,Runnable>();var menu=menu(p,"Срок поручения",actions);int slot=19;for(int hours:new int[]{1,8,24,168}){button(menu,actions,slot++,Material.CLOCK,hours+" ч.",List.of("&7Житель: &f"+CouncilMenus.name(resident),"&7Действие: &f"+action.title(),"&7Перед выдачей покажем точную дату окончания."),()->propose(p,town,resident,action,hours,"Временное поручение мэра"));}p.openInventory(menu);}
    private void propose(Player p,Town town,UUID resident,TownAction action,int hours,String reason){var g=service.proposal(p,town,resident,action,hours,reason);long revision=service.state().revision();quote(p,"Выдать временные права",g,()->service.grant(p,g,revision));}
    private void revoke(Player p,Town town,Grant g){if(!council.mayEditAccess(p,town))throw new IllegalArgumentException("Отзыв доступен действующему мэру");quote(p,"Отозвать временные права",g,()->service.revoke(p,g,"Отозвано действующим мэром"));}
    private void quote(Player p,String title,Grant g,Supplier<CompletionStage<State>> action){long now=System.currentTimeMillis();quotes.entrySet().removeIf(e->e.getValue().expires()<now);if(quotes.size()>=512&&!quotes.containsKey(p.getUniqueId()))throw new IllegalArgumentException("Повторите позже: много открытых подтверждений");var q=new Quote(UUID.randomUUID(),now+60_000,action);quotes.put(p.getUniqueId(),q);var actions=new HashMap<Integer,Runnable>();var menu=menu(p,title,actions);button(menu,actions,13,Material.PAPER,title,List.of("&7Житель: &f"+CouncilMenus.name(g.resident()),"&7Действие: &f"+TownAction.parse(g.action()).title(),"&7Окончание: &f"+date(g.expiresAt()),"&7Причина: &f"+g.reason(),"&7Должности, личные правила и ранги не меняются.","&7Расход денег регулируется действующими правилами казны."),null);button(menu,actions,29,Material.LIME_DYE,"Подтвердить",List.of("&7Действует 60 секунд; права проверим повторно."),()->confirm(p,q.id()));button(menu,actions,33,Material.GRAY_DYE,"Отмена",List.of(),()->{quotes.remove(p.getUniqueId(),q);open(p,council.ownTown(p.getUniqueId()),0);});p.openInventory(menu);}
    private void confirm(Player p,UUID id){var q=quotes.get(p.getUniqueId());if(q==null||!q.id().equals(id)||q.expires()<System.currentTimeMillis())throw new IllegalArgumentException("Подтверждение устарело. Откройте действие заново");quotes.remove(p.getUniqueId(),q);var window=p.getOpenInventory().getTopInventory();var receipt=q.action().get();tell(p,"Сохраняем поручение…");receipt.whenComplete((state,error)->{if(!plugin.isEnabled()||SuiteState.frozen(plugin.getName()))return;SuiteScheduler.player(plugin,p,who->{if(error!=null){Throwable cause=error;while(cause.getCause()!=null)cause=cause.getCause();tell(who,"&cИзменение не подтверждено: "+cause.getMessage());return;}tell(who,"&aПоручение сохранено.");if(who.getOpenInventory().getTopInventory()==window){var town=council.ownTown(who.getUniqueId());if(town!=null)open(who,town,0);}});});}
    @EventHandler public void click(InventoryClickEvent event){try(var guard=SuiteState.guard()){var top=event.getView().getTopInventory();if(!(top.getHolder() instanceof View v))return;event.setCancelled(true);if(SuiteState.frozen(plugin.getName())||!(event.getWhoClicked() instanceof Player p)||!p.getUniqueId().equals(v.viewer()))return;var action=v.actions().get(event.getRawSlot());if(action!=null)SuiteScheduler.entity(plugin,p,()->{if(p.getOpenInventory().getTopInventory()!=top)return;try{action.run();}catch(Exception error){tell(p,"&c"+error.getMessage());}});}}
    @EventHandler public void drag(InventoryDragEvent event){if(event.getView().getTopInventory().getHolder() instanceof View)event.setCancelled(true);}
    @EventHandler public void quit(PlayerQuitEvent event){try(var guard=SuiteState.guard()){quotes.remove(event.getPlayer().getUniqueId());}}
    public void close(){quotes.clear();}
}
